//! End-to-end OCR proof — the real engine stack, the real pinned
//! eng.traineddata, a real rendered text image. Ignored by default;
//! run explicitly (after fetch.sh / fetch.ps1):
//!
//!   OK_E2E=1 OK_TESSDATA=vendor/tessdata \
//!   cargo test --test e2e -- --ignored --nocapture
//!
//! The fixture (tests/fixtures/hello-ocr.png, generated by
//! tools/make_fixture.py) renders one line — "The quick brown fox
//! jumps over the lazy dog 12345" — in DejaVu Sans. The assertions
//! check that phrase and the digits survive OCR and that the mean
//! confidence is solidly positive; exact-text equality would be a
//! brittle claim about a neural/legacy recognizer, so we assert the
//! content that proves the pipeline works.

use std::ffi::{CStr, CString};
use std::os::raw::c_char;
use std::path::{Path, PathBuf};

use ocrkit::ffi::{
    ok_engine_create, ok_engine_free, ok_free_string, ok_last_error, ok_recognize_file,
    ok_recognize_png, ok_set_variable,
};

fn cs(s: &str) -> CString {
    CString::new(s).unwrap()
}

fn take(p: *mut c_char) -> String {
    assert!(!p.is_null(), "recognition returned null");
    let s = unsafe { CStr::from_ptr(p) }.to_str().unwrap().to_string();
    ok_free_string(p);
    s
}

fn last_error() -> String {
    unsafe { CStr::from_ptr(ok_last_error()) }
        .to_string_lossy()
        .into_owned()
}

fn fixture_png() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("hello-ocr.png")
}

/// Pull the integer after "confidence": out of the result JSON.
fn confidence_of(json: &str) -> i32 {
    let start = json
        .find("\"confidence\": ")
        .expect("confidence key present")
        + "\"confidence\": ".len();
    let rest = &json[start..];
    let end = rest
        .find(|c: char| !(c.is_ascii_digit() || c == '-'))
        .unwrap_or(rest.len());
    rest[..end].parse().expect("confidence is an integer")
}

fn assert_fox_json(json: &str) {
    println!("OCR JSON: {json}");
    let lower = json.to_lowercase();
    assert!(
        lower.contains("the quick brown fox"),
        "phrase not recognized: {json}"
    );
    assert!(lower.contains("12345"), "digits not recognized: {json}");
    let conf = confidence_of(json);
    println!("mean confidence: {conf}");
    assert!(conf > 50, "confidence too low: {conf}");
}

#[test]
#[ignore = "needs the OCR engine + pinned tessdata (OK_E2E, OK_TESSDATA)"]
fn fox_image_recognition() {
    assert_eq!(
        std::env::var("OK_E2E").as_deref(),
        Ok("1"),
        "set OK_E2E=1 to run the e2e OCR proof"
    );
    let tessdata = std::env::var("OK_TESSDATA")
        .unwrap_or_else(|_| panic!("OK_TESSDATA must be set (dir holding eng.traineddata)"));
    assert!(
        Path::new(&tessdata).join("eng.traineddata").is_file(),
        "{tessdata}/eng.traineddata missing (run fetch.sh / fetch.ps1 first)"
    );

    let eng = ok_engine_create(cs(&tessdata).as_ptr(), cs("eng").as_ptr());
    assert!(eng != 0, "engine creation failed: {}", last_error());

    // A variable Tesseract knows must be accepted.
    assert_eq!(
        ok_set_variable(eng, cs("tessedit_pageseg_mode").as_ptr(), cs("6").as_ptr()),
        0
    );

    let png = fixture_png();
    assert!(png.is_file(), "fixture missing: {}", png.display());

    // Path 1: recognize from the file.
    let json_file = take(ok_recognize_file(eng, cs(png.to_str().unwrap()).as_ptr()));
    assert_fox_json(&json_file);

    // Path 2: recognize the same image from memory bytes.
    let bytes = std::fs::read(&png).unwrap();
    let json_mem = take(ok_recognize_png(eng, bytes.as_ptr(), bytes.len()));
    assert_fox_json(&json_mem);

    assert_eq!(ok_engine_free(eng), 0);
}
